package paige.navic.domain.manager

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import paige.navic.domain.models.settings.StationCharacter

/*
 * Stations: radio and autoplay generated by the hub (navi-connect PROTOCOL §18, I-040).
 *
 * The wire shapes of `/sonic/station/...`, what this device keeps about the station that built its
 * queue, and every decision the autoplay driver and the queue sheet make about them, as pure
 * functions (`StationDriverTest`). `StationManager` does the HTTP; `RadioManager` acts.
 *
 * Words: in the UI a seeded station is a "radio" and the seedless one "Your mix". "Station" is the
 * noun in code and on the wire only; it already names Subsonic internet radio in this app.
 */

/** Feature name in `welcome.features` (PROTOCOL §3.1) for a hub with the engine. */
const val HUB_FEATURE_STATION = "station"

/**
 * Feature name for a hub that edits the session's bound station's queue itself on a `signal` with
 * `apply: true` (S-035): it takes the station's songs out after its cut, puts a fresh batch in for a
 * character, and tells the playing device with `queueChanged`.
 */
const val HUB_FEATURE_STATION_EDITS = "stationEdits"

/**
 * Why a station exists (`start.origin`, echoed in every answer, the `station` frame and
 * `welcome.station`). A RADIO was asked for (a track's, an album's, an artist's, Your mix, a
 * mix) and keeps going whether or not autoplay is on; a CONTINUE is autoplay carrying on a
 * queue no station built, and stops with autoplay.
 */
const val ORIGIN_RADIO = "radio"
const val ORIGIN_CONTINUE = "continue"

/**
 * A station's origin: the hub's echo; else, for an older hub that echoes none, what this
 * device sent when its own entry point started it; else (a station another device started,
 * from a hub that says nothing) a continuation.
 */
fun stationOrigin(echoed: String?, sentHere: String?): String =
	echoed?.takeIf { it.isNotBlank() } ?: sentHere?.takeIf { it.isNotBlank() } ?: ORIGIN_CONTINUE

/** One character as the hub's catalogue words it (`GET /sonic/station/characters`). */
@Serializable
data class StationCharacterInfo(
	val id: String = "",
	val label: String = "",
	val description: String = "",
	val legacy: String = ""
)

/**
 * The probe's answer. Always 200 from a hub with the routes: [configured] false means the engine
 * is off, [available] false that no tier answered its last probe. [engine] is `tier2` (AudioMuse)
 * or `tier1` (Navidrome only), null when neither.
 */
@Serializable
data class StationCatalogue(
	val configured: Boolean = false,
	val available: Boolean = false,
	val engine: String? = null,
	val default: String = StationCharacter.Default.wireId,
	val characters: List<StationCharacterInfo> = emptyList()
) {
	/** The catalogue's words for [character], or the bundled ones. */
	fun infoFor(character: StationCharacter): StationCharacterInfo =
		characters.firstOrNull { it.id == character.wireId }
			?: BUNDLED.characters.first { it.id == character.wireId }

	companion object {
		/**
		 * The catalogue PROTOCOL §18.1 specifies, for a hub that has not answered yet. Never says
		 * available: that is learned from a hub, per process.
		 */
		val BUNDLED = StationCatalogue(
			characters = listOf(
				StationCharacterInfo(
					"close", "Close", "Stays right next to what you started with.", "EchoMatch"
				),
				StationCharacterInfo(
					"balanced", "Balanced", "Near what you started with, with room to move.", "SteadyVibes"
				),
				StationCharacterInfo(
					"explore", "Explore", "Wanders further, steered by what you skip and like.", "TransitionMaestro"
				)
			)
		)
	}
}

/** What a station is seeded from. `track` and `tracks` carry ids (1, or 1–5); `yourMix` none. */
@Serializable
data class StationSeed(
	val kind: String,
	val ids: List<String> = emptyList(),
	val name: String? = null
) {
	companion object {
		const val TRACK = "track"
		const val TRACKS = "tracks"
		const val YOUR_MIX = "yourMix"

		val YourMix = StationSeed(YOUR_MIX)
	}
}

@Serializable
data class StationTrack(
	val id: String = "",
	val title: String = "",
	val artist: String = "",
	val album: String = "",
	val why: String = "",
	val rank: Int? = null
)

/** `start` and `next` answer with this shape; fields one of them lacks are left at their defaults. */
@Serializable
data class StationAnswer(
	val stationId: String = "",
	val name: String = "",
	val character: String = "",
	val engine: String? = null,
	val seed: StationSeed? = null,
	val seq: Int = 0,
	val rev: Int = 0,
	val tracks: List<StationTrack> = emptyList(),
	val exhausted: Boolean = false,
	val partial: Boolean = false,
	val servedElsewhere: Boolean = false,
	/**
	 * The station was stopped (`signal stop`, from any device, I-041): `next` answers no tracks and
	 * this flag until a `character` signal starts it again. False from a hub that predates it.
	 */
	val stopped: Boolean = false,
	/** [ORIGIN_RADIO] or [ORIGIN_CONTINUE], echoed; null from a hub that does not say. */
	val origin: String? = null,
	/** `start` only: whether `bindSession` bound the session. Null from a hub that does not say. */
	val bound: Boolean? = null
)

@Serializable
internal data class StationStartBody(
	val seed: StationSeed,
	val character: String? = null,
	val count: Int,
	val exclude: List<String>,
	val bindSession: String? = null,
	val deviceId: String? = null,
	val origin: String
)

@Serializable
internal data class StationNextBody(
	val stationId: String,
	val after: Int,
	val count: Int,
	val exclude: List<String>,
	val deviceId: String? = null
)

@Serializable
internal data class StationSignalBody(
	val stationId: String,
	val trackId: String,
	val kind: String,
	val value: String? = null,
	/** Sent only when true (`encodeDefaults = false`): the hub edits the queue (S-035). */
	val apply: Boolean = false
)

/** What the hub did with a `signal` sent with `apply: true` (S-035). */
data class StationEditAnswer(
	val applied: Boolean,
	/** The edit, or null for `edited: false` (nothing done to the queue; [reason] may say why). */
	val edited: StationEdit?,
	val reason: String?
)

/** `edited: {removed, added, from}`: how many rows went, how many came, from which index. */
data class StationEdit(val removed: Int, val added: Int, val from: Int?)

/**
 * Read a `signal` answer `{rev, applied, edited: {removed, added, from} | false, reason?}`. A count
 * may come as a number or as the list of ids; null when the body is not an answer at all.
 */
fun parseStationEditAnswer(text: String): StationEditAnswer? {
	val obj = runCatching { Json.parseToJsonElement(text) }.getOrNull()
		as? JsonObject ?: return null
	fun count(element: JsonElement?): Int = when (element) {
		is JsonArray -> element.size
		is JsonPrimitive -> element.content.toIntOrNull() ?: 0
		else -> 0
	}
	val edited = (obj["edited"] as? JsonObject)?.let { e ->
		StationEdit(
			removed = count(e["removed"]),
			added = count(e["added"]),
			from = (e["from"] as? JsonPrimitive)?.content?.toIntOrNull()
		)
	}
	val applied = (obj["applied"] as? JsonPrimitive)?.content == "true"
	val reason = (obj["reason"] as? JsonPrimitive)?.takeUnless { it is JsonNull }?.content
	return StationEditAnswer(applied = applied, edited = edited, reason = reason)
}

/** A refusal's body: `{code, stationId}` for 4xx, `{fallback: true}` for 503. */
@Serializable
internal data class StationRefusal(
	val code: String? = null,
	val stationId: String? = null,
	val fallback: Boolean = false
)

/** How one `start` or `next` came back. */
sealed interface StationResult {
	data class Ok(val answer: StationAnswer) : StationResult

	/** 409 `session_bound`: the session already has [stationId]; continue that one with `next`. */
	data class SessionBound(val stationId: String) : StationResult

	/** 404 `station_unknown`: expired, or a hub that lost it. Start again once from the seed. */
	data object StationUnknown : StationResult

	/**
	 * The hub refused what was asked (400 `bad_seed`, 404 `seed_unknown`, another 4xx with a
	 * reason). Asking again at once would be refused again: wait for the next trigger.
	 */
	data class Refused(val code: String) : StationResult

	/**
	 * Worth asking again: a timeout or a connection error while the hub socket is up, a 5xx
	 * other than 503, a 429 or a 408. Never a reason to fall back to Auto DJ, and never a
	 * reason to stop asking the engine.
	 */
	data class Transient(val reason: String) : StationResult

	/**
	 * No station can be had: 503, a `{fallback: true}` body, no hub configured, a hub without the
	 * engine or whose probe said unavailable, the hub disconnected, a bare 404, or 401/403. The
	 * caller runs its own fallback (Auto DJ for autoplay, Navidrome's similar songs for a radio).
	 */
	data class Fallback(val reason: String) : StationResult
}

/**
 * How a `start` / `next` that did not answer 200 is read (Feishin's classification, I-040).
 * [status] null is a request that never got an answer (timeout, connection error): transient
 * while the hub socket is up, a fallback when the hub is disconnected.
 */
internal fun stationFailure(status: Int?, refusal: StationRefusal?, hubConnected: Boolean): StationResult {
	if (status == null) {
		return if (hubConnected) StationResult.Transient("no answer") else StationResult.Fallback("hub disconnected")
	}
	if (status == 503 || refusal?.fallback == true) return StationResult.Fallback("HTTP $status")
	val code = refusal?.code.orEmpty()
	val boundTo = refusal?.stationId.orEmpty()
	return when {
		status == 409 && code == "session_bound" && boundTo.isNotBlank() -> StationResult.SessionBound(boundTo)
		status == 404 && code == "station_unknown" -> StationResult.StationUnknown
		status == 404 && code.isNotBlank() -> StationResult.Refused(code)
		// No code: a hub without the route after all.
		status == 404 -> StationResult.Fallback("HTTP 404")
		status == 401 || status == 403 -> StationResult.Fallback("HTTP $status")
		status == 408 || status == 429 || status >= 500 -> StationResult.Transient("HTTP $status")
		status in 400..499 -> StationResult.Refused(code.ifBlank { "http_$status" })
		else -> StationResult.Transient("HTTP $status")
	}
}

/** Transient failures of one trigger are asked again this many times, this far apart. */
const val STATION_TRANSIENT_RETRIES = 3
const val STATION_TRANSIENT_RETRY_MS = 8_000L

/** What the driver does after a `start` / `next` that did not succeed. */
enum class StationFailureAction {
	/** Ask again in [STATION_TRANSIENT_RETRY_MS], for the same trigger. */
	RetrySoon,
	/** Nothing until the playing song or the songs left change. */
	WaitForNextTrigger,
	/** Auto DJ tops this queue up. */
	AutoDj,
	/** Start again once from the recorded seed. */
	Restart,
	/** The session already has a station: continue that one. */
	ContinueSessionStation
}

/**
 * The driver's answer to [result], with [transientAttempts] retries of this trigger already
 * made. Auto DJ only on a real fallback, and only with autoplay on: it obeys the switch, and its
 * random steps are what stations exist to keep out of a radio.
 */
fun stationFailureAction(result: StationResult, autoplayOn: Boolean, transientAttempts: Int): StationFailureAction =
	when (result) {
		is StationResult.Transient ->
			if (transientAttempts < STATION_TRANSIENT_RETRIES) StationFailureAction.RetrySoon
			else StationFailureAction.WaitForNextTrigger
		is StationResult.Fallback ->
			if (autoplayOn) StationFailureAction.AutoDj else StationFailureAction.WaitForNextTrigger
		is StationResult.Refused -> StationFailureAction.WaitForNextTrigger
		StationResult.StationUnknown -> StationFailureAction.Restart
		is StationResult.SessionBound -> StationFailureAction.ContinueSessionStation
		is StationResult.Ok -> StationFailureAction.WaitForNextTrigger
	}

/**
 * The station that built this device's current queue, persisted (`PreferenceManager.
 * stationProvenance`) so a restart keeps it. [queueId] is the saved-queue id of the queue it
 * belongs to (`PlayerUiState.savedQueueId`): a new queue has another id, which is how a new album
 * or playlist stops being "the radio" without anything clearing this.
 *
 * [seq] is the station's cursor as this device last applied it (`after` on the next `next`).
 * [lastFromAutoDj] is true when the newest top-up of this queue came from Auto DJ because the hub
 * could not be had, so the queue sheet says so.
 */
@Serializable
data class StationProvenance(
	val queueId: String,
	val stationId: String,
	val name: String = "",
	val character: String = StationCharacter.Default.wireId,
	val engine: String? = null,
	val seed: StationSeed? = null,
	val seq: Int = 0,
	val rev: Int = 0,
	val exhausted: Boolean = false,
	val lastFromAutoDj: Boolean = false,
	/** The hub's echo, else what this device sent; see [stationOrigin]. */
	val origin: String? = null,
	/**
	 * This device asked `start` to bind the session and the hub answered `bound: false`: the
	 * station is continued from here without binding, so its id is not put on this queue's
	 * `setQueue`, and the bind is not tried again.
	 */
	val unbound: Boolean = false,
	/** Stopped for every device (the Off chip, I-041): nothing more is added until a character chip. */
	val stopped: Boolean = false,
	/**
	 * The ids this station added to this queue, as this device saw them (a radio's first batch,
	 * every top-up), newest last, at most [SERVED_KEEP]. The Off and character chips remove or
	 * replace only these, never a song the user put in (I-041).
	 */
	val served: List<String> = emptyList()
) {
	/** [ORIGIN_RADIO] or [ORIGIN_CONTINUE], as recorded; kept for the record, no longer a rule. */
	val effectiveOrigin: String get() = stationOrigin(origin, null)

	/** [served] with [ids] added, the oldest dropped past [SERVED_KEEP]. */
	fun withServed(ids: List<String>): StationProvenance =
		if (ids.isEmpty()) this else copy(served = (served + ids).takeLast(SERVED_KEEP))

	companion object {
		const val SERVED_KEEP = 300
	}
}

/** The `station` frame and `welcome.station` (PROTOCOL §18.2); [name] / [seed] in welcome only. */
data class HubStationFrame(
	val stationId: String,
	val seq: Int,
	val rev: Int,
	val character: String,
	val exhausted: Boolean,
	val name: String? = null,
	val seed: StationSeed? = null,
	val origin: String? = null,
	val stopped: Boolean = false
)

/** A station's provenance after an answer was applied to its queue. */
internal fun StationProvenance.applied(answer: StationAnswer): StationProvenance = copy(
	stationId = answer.stationId.ifBlank { stationId },
	name = answer.name.ifBlank { name },
	character = answer.character.ifBlank { character },
	engine = answer.engine ?: engine,
	seed = answer.seed ?: seed,
	seq = maxOf(seq, answer.seq),
	rev = maxOf(rev, answer.rev),
	exhausted = answer.exhausted,
	lastFromAutoDj = false,
	origin = answer.origin?.takeIf { it.isNotBlank() } ?: origin,
	stopped = answer.stopped
)

/** What one `start` / `next` answer does: the record after it, the ids to append, and whether to ask again soon. */
data class StationBatch(
	val provenance: StationProvenance,
	val append: List<String>,
	val retrySoon: Boolean
)

/**
 * Apply [answer] to the queue [bound] belongs to, holding [queued]. Served elsewhere: another
 * device topped the station up (its batch reaches this queue through the session), so only the
 * cursor is taken and nothing is asked again at once. Otherwise the station's new tracks not
 * already queued are appended, and an answer with none that is not `exhausted` (a `partial`
 * one, or every track already queued) is asked again soon. [fresh]: the record of a station
 * just started, whose cursor is the answer's whatever the record held.
 */
fun stationBatch(
	bound: StationProvenance,
	answer: StationAnswer,
	queued: Set<String>,
	fresh: Boolean,
	askedToBind: Boolean = false
): StationBatch {
	if (answer.servedElsewhere) {
		return StationBatch(bound.copy(seq = maxOf(bound.seq, answer.seq)), emptyList(), retrySoon = false)
	}
	val ids = answer.tracks.map { it.id }.filter { it.isNotBlank() && it !in queued }.distinct()
	val applied = bound.applied(answer)
		.let { if (fresh) it.copy(seq = answer.seq, rev = answer.rev) else it }
		.let { if (askedToBind && answer.bound == false) it.copy(unbound = true) else it }
		.withServed(ids)
	return StationBatch(applied, ids, retrySoon = ids.isEmpty() && !answer.exhausted && !answer.stopped)
}

/**
 * The record to keep for [bound], the station this queue belongs to as the driver sees it, when
 * it is not the one recorded here: a station another device bound the session to, met by this
 * device while it plays the session. Kept, so that when the hub later forgets it (and the
 * session stops naming it) the queue still knows its station and [stationRestart] brings it back
 * as itself (B-139). Null when it is already the record.
 */
fun adoptedStationRecord(bound: StationProvenance?, recorded: StationProvenance?): StationProvenance? =
	bound?.takeIf { it.stationId != recorded?.stationId || it.queueId != recorded?.queueId }

/** What brings back a station the hub lost ([stationRestart]). */
data class StationRestart(
	val seed: StationSeed,
	val character: StationCharacter?,
	val origin: String
)

/**
 * The `start` that brings back a station the hub lost: a `next` answered 404 (expired, or a hub
 * that forgot it). It is the same station picking up again, so it keeps its character and its
 * name, and its own seed when this device knows it.
 *
 * B-139: a station another device started and this one continued has no seed here (frames carry
 * none). Brought back, it went on as a NEW continuation of the queue: named after the playing
 * song and in this device's own character, so "Take a Picture radio · Close" came back as
 * "I Don't Wanna Lose radio · Balanced" at a top-up. Without its seed it is now seeded from the
 * queue's last songs ([recentIds]) under its own name: the hub calls a station "<seed name> radio",
 * so that name goes back as the seed's ("Your mix" is a Your mix seed again). Null when there is
 * nothing to seed from. [character] is null when the station's own is not known here either; the
 * caller then uses its preference, as any start does.
 */
fun stationRestart(bound: StationProvenance, recentIds: List<String>, playingTitle: String?): StationRestart? {
	val seed = bound.seed ?: when {
		bound.name.trim() == YOUR_MIX_STATION_NAME -> StationSeed.YourMix
		recentIds.isEmpty() -> return null
		else -> StationSeed(StationSeed.TRACKS, recentIds, stationSeedName(bound.name) ?: playingTitle)
	}
	return StationRestart(seed, StationCharacter.fromWire(bound.character), bound.effectiveOrigin)
}

/** The hub's name for a Your mix station. */
const val YOUR_MIX_STATION_NAME = "Your mix"

/** The seed name a station called [stationName] was started from (the hub names it "<seed name> radio"). */
fun stationSeedName(stationName: String): String? =
	stationName.trim().takeIf { it.endsWith(" radio") }?.removeSuffix(" radio")?.trim()?.ifEmpty { null }

/** A `station` frame for this provenance's station, laid over it. Frames for another station change nothing. */
internal fun StationProvenance.withFrame(frame: HubStationFrame): StationProvenance =
	if (frame.stationId != stationId) this
	else copy(
		seq = maxOf(seq, frame.seq),
		rev = maxOf(rev, frame.rev),
		character = frame.character.ifBlank { character },
		exhausted = frame.exhausted,
		name = frame.name?.takeIf { it.isNotBlank() } ?: name,
		origin = frame.origin?.takeIf { it.isNotBlank() } ?: origin,
		stopped = frame.stopped
	)

// --------------------------------------------------------------------------------------------- //
// Play order
// --------------------------------------------------------------------------------------------- //

/**
 * How many songs are left after the playing one, in the order the player will play them.
 * [order] is the queue indices in play order (the shuffle order), or null for queue order. An
 * order that does not hold [currentIndex] (a timeline mid-change) is read as queue order.
 */
fun playOrderRemaining(order: List<Int>?, queueSize: Int, currentIndex: Int): Int {
	if (queueSize <= 0 || currentIndex < 0) return 0
	if (order != null && order.size == queueSize) {
		val at = order.indexOf(currentIndex)
		if (at >= 0) return order.size - at - 1
	}
	return (queueSize - currentIndex - 1).coerceAtLeast(0)
}

/** Up to [n] queue indices played just before [currentIndex], newest first, then the playing one first. */
fun playOrderRecent(order: List<Int>?, queueSize: Int, currentIndex: Int, n: Int): List<Int> {
	if (queueSize <= 0 || currentIndex !in 0 until queueSize || n <= 0) return emptyList()
	val sequence = if (order != null && order.size == queueSize && currentIndex in order) order
	else (0 until queueSize).toList()
	val at = sequence.indexOf(currentIndex)
	return (at downTo maxOf(0, at - n + 1)).map { sequence[it] }
}

// --------------------------------------------------------------------------------------------- //
// The autoplay driver's decision
// --------------------------------------------------------------------------------------------- //

/** Ask for more when fewer than this many songs are left after the playing one (play order). */
const val STATION_LOOKAHEAD = 2

/** How many songs one `next` asks for: a short lookahead, so skips steer the next batch soon. */
const val STATION_BATCH = 5

/**
 * How long a station-bound queue waits after another device topped its station up (a
 * `servedElsewhere` answer, or a `station` frame moving the cursor while this device asked
 * nothing): that batch reaches this queue through the session. Asking again at once with the new
 * cursor added a second batch for the same top-up. Feishin's SERVED_ELSEWHERE_GRACE_MS.
 */
const val STATION_ELSEWHERE_GRACE_MS = 8_000L

/** What autoplay should do for one look at the local player. */
sealed interface AutoplayStep {
	/** Nothing now. */
	data object Idle : AutoplayStep

	/** Continue [stationId] from [after]. */
	data class Next(val stationId: String, val after: Int) : AutoplayStep

	/** The queue is no station's: start one from its last tracks and bind it to the session. */
	data object Start : AutoplayStep

	/** No engine: Auto DJ tops the queue up. */
	data object AutoDj : AutoplayStep

	/** The station has nothing left that fits: autoplay stops, and the queue sheet says so. */
	data object Exhausted : AutoplayStep
}

/** Everything [autoplayStep] decides from, read at one moment. */
data class AutoplayLook(
	val autoplayOn: Boolean,
	/** Another hub device is playing: this device's player is frozen, the playing one tops up. */
	val remoteActive: Boolean,
	val paused: Boolean,
	val repeatMode: Int,
	val queueSize: Int,
	val currentIndex: Int,
	/** Songs left after the playing one, in play order ([playOrderRemaining]). */
	val remaining: Int,
	val stationsAvailable: Boolean,
	/** The station this queue belongs to, if any ([boundStation]). */
	val bound: StationProvenance?,
	/** A `start` / `next` / Auto DJ top-up is already out: one at a time. */
	val inFlight: Boolean,
	val autoDjTiming: Int,
	/** Another device topped the bound station up in the last [STATION_ELSEWHERE_GRACE_MS]. */
	val elsewhereRecent: Boolean = false,
	/** A chip tap asked for this look: it decides paused too (S-035, Feishin's B-144). */
	val chipTap: Boolean = false
)

/**
 * The driver's rule. Local playback only; nothing while paused, repeating (the queue loops or
 * holds) or with a request out. With the engine, a station-bound queue asks `next` when fewer
 * than [STATION_LOOKAHEAD] songs are left and stops for good once the station is exhausted; a
 * queue no station built asks `start` at the same point. Without it, Auto DJ at its own timing.
 *
 * Off stops everything, radios included (I-041; the Off chip): nothing is asked and nothing is
 * started. A station stopped by any device ([StationProvenance.stopped]) adds nothing either.
 */
fun autoplayStep(look: AutoplayLook): AutoplayStep {
	if (!look.autoplayOn || look.remoteActive || look.inFlight) return AutoplayStep.Idle
	// Paused waits for playback, except right after a chip: a character picked on a paused queue
	// on its last song is a request for more now, not at the next play.
	if ((look.paused && !look.chipTap) || look.repeatMode != 0) return AutoplayStep.Idle
	if (look.queueSize <= 0 || look.currentIndex !in 0 until look.queueSize) return AutoplayStep.Idle
	if (!look.stationsAvailable) {
		return if (autoDjDue(look.remaining, look.autoDjTiming)) AutoplayStep.AutoDj else AutoplayStep.Idle
	}
	if (look.remaining >= STATION_LOOKAHEAD) return AutoplayStep.Idle
	val bound = look.bound ?: return AutoplayStep.Start
	if (bound.stopped) return AutoplayStep.Idle
	if (bound.exhausted) return AutoplayStep.Exhausted
	// Its batch is on its way through the session; the driver looks again after the grace.
	if (look.elsewhereRecent) return AutoplayStep.Idle
	return AutoplayStep.Next(bound.stationId, bound.seq)
}

/**
 * The station a queue belongs to. The local record when it is this queue's ([queueId]) and the
 * session does not name another; else, while this device plays the hub session, the session's own
 * station ([sessionStationId], from `session.stationId`, passed only then): a queue handed here by
 * a transfer continues the station it was, from the cursor the hub last broadcast ([frameOf]).
 * A session station this device has no record of has no seed here (frames carry none); the
 * driver keeps it as the record ([adoptedStationRecord]) and brings it back from the queue's last
 * songs if the hub loses it ([stationRestart]).
 */
fun boundStation(
	provenance: StationProvenance?,
	queueId: String?,
	sessionStationId: String?,
	frameOf: (String) -> HubStationFrame?,
	sessionName: String?
): StationProvenance? {
	if (queueId == null) return null
	if (provenance != null && (provenance.queueId == queueId || provenance.stationId == sessionStationId) &&
		(sessionStationId == null || sessionStationId == provenance.stationId)
	) {
		val mine = provenance.copy(queueId = queueId)
		return frameOf(mine.stationId)?.let { mine.withFrame(it) } ?: mine
	}
	if (sessionStationId == null) return null
	val frame = frameOf(sessionStationId)
	return StationProvenance(
		queueId = queueId,
		stationId = sessionStationId,
		name = frame?.name ?: sessionName.orEmpty(),
		// Not known until the station's frame is (B-139): an empty character is said as none,
		// never as the default, which named a Balanced that no device had chosen.
		character = frame?.character.orEmpty(),
		seed = frame?.seed,
		seq = frame?.seq ?: 0,
		rev = frame?.rev ?: 0,
		exhausted = frame?.exhausted ?: false,
		origin = frame?.origin,
		stopped = frame?.stopped ?: false
	)
}

// --------------------------------------------------------------------------------------------- //
// What the queue sheet says built the queue
// --------------------------------------------------------------------------------------------- //

/** The queue sheet's line about what built the queue. Never read from the autoplay preference. */
sealed interface QueueGenerator {
	/** A station: "Cinnamon Girl radio · Balanced", "… · via Navidrome" when Navidrome answered. */
	data class Station(
		val name: String,
		/** Null while the station's character is not known on this device (no frame yet). */
		val character: StationCharacter?,
		val viaNavidrome: Boolean,
		val yourMix: Boolean
	) : QueueGenerator

	/** The station is stopped (the Off chip, from any device): nothing more is added. */
	data class Stopped(val name: String, val yourMix: Boolean) : QueueGenerator

	/** The station has nothing left that fits; [offerExplore] when it is not on Explore already. */
	data class Exhausted(val name: String, val offerExplore: Boolean) : QueueGenerator

	/** Auto DJ topped this queue up (no engine, or the hub could not be had for that top-up). */
	data object AutoDj : QueueGenerator

	/** A mix built here without the engine (the old radio, a journey, a mix). */
	data object AudioMuseMix : QueueGenerator
}

/**
 * The line for the current queue. [bound] is the station it belongs to ([boundStation]);
 * [autoDjQueueId] the queue Auto DJ last topped up; [generatedMix] whether the queue is exactly a
 * mix generated here without a station.
 */
fun queueGenerator(
	bound: StationProvenance?,
	queueId: String?,
	autoDjQueueId: String?,
	generatedMix: Boolean
): QueueGenerator? {
	if (bound != null) {
		if (bound.lastFromAutoDj) return QueueGenerator.AutoDj
		val character = StationCharacter.fromWire(bound.character)
		val yourMix = bound.seed?.kind == StationSeed.YOUR_MIX
		if (bound.stopped) return QueueGenerator.Stopped(bound.name, yourMix)
		if (bound.exhausted) {
			return QueueGenerator.Exhausted(bound.name, offerExplore = character != StationCharacter.Explore)
		}
		return QueueGenerator.Station(
			name = bound.name,
			character = character,
			viaNavidrome = bound.engine == ENGINE_TIER1,
			yourMix = yourMix
		)
	}
	if (queueId != null && queueId == autoDjQueueId) return QueueGenerator.AutoDj
	if (generatedMix) return QueueGenerator.AudioMuseMix
	return null
}

/** `engine` when Navidrome alone answered (AudioMuse down, or not configured on the hub). */
const val ENGINE_TIER1 = "tier1"

// --------------------------------------------------------------------------------------------- //
// Seeds
// --------------------------------------------------------------------------------------------- //

/** Up to [n] items spread evenly over [items], first and last included: an album radio's seed. */
fun <T> spreadPick(items: List<T>, n: Int): List<T> {
	if (n <= 0 || items.isEmpty()) return emptyList()
	if (items.size <= n) return items
	if (n == 1) return listOf(items.first())
	val step = (items.size - 1).toDouble() / (n - 1)
	return (0 until n).map { items[(it * step + 0.5).toInt().coerceAtMost(items.lastIndex)] }.distinct()
}

/** The most an `exclude` list may carry (PROTOCOL §18.1). The newest are kept. */
const val STATION_EXCLUDE_MAX = 1000

fun stationExclude(queueIds: List<String>): List<String> =
	queueIds.distinct().takeLast(STATION_EXCLUDE_MAX)
